#!/usr/bin/env bash
# Gate engine_api_conformance (layer `api`), engine-agnostic: the backend's api/README.md
# manifest matches api/; nothing outside the backend includes a non-api/ header of it;
# every api/ header compiles on its own with the flags of the code that includes it
# (target api_conformance_<engine>, generated by cmake/Backend.cmake); after the build the
# required introspection hooks (api_contract.md section 3) are called through `host.sh sql -`
# on a server engine and must not error (on an embedded engine they exist only on the
# backend's own in-process connections, where the layer harnesses call them). The engine
# comes from the gate context.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
export ROOT

# shellcheck source=aux_gate_common.sh
source "$(dirname "${BASH_SOURCE[0]}")/aux_gate_common.sh"
load_engine_gate_context "${ROOT}" 0

JSON="${ACCEL_GATE_OUT:-/tmp/engine_api_conformance.json}"
fail() { emit_result "${JSON}" engine_api_conformance fail "$1" "${2:-}" "engine=${ENGINE_NAME}"; }

log="$(python3 "${ROOT}/pipeline/gates/check_api_manifest.py" "${ROOT}" "${ENGINE_NAME}" 2>&1)" \
  || fail "api/README.md does not match api/" "${log}"
log="$(python3 "${ROOT}/scripts/check_layer_includes.py" --root "${ROOT}" 2>&1)" \
  || fail "include boundary: only backends/<engine>/api/ may be included from outside the backend" "${log}"
engine_steps "up" "build api_conformance_${ENGINE_NAME}" "build" \
  || fail "an api/ header does not compile on its own: ${ENGINE_FAIL}" "${ENGINE_LOG}"
# Hooks of api_contract.md section 3: the required ones always, the optional invalidation hook
# when the manifest's introspection row lists it (a hook the manifest leaves out is n/a).
hooks=("accel_get_execute_counts()" "accel_get_last_maintenance_action()"
       "accel_get_last_maintenance_decision()" "accel_set_force_maintenance_action('')")
if python3 -c "
import sys; sys.path.insert(0, sys.argv[1])
from check_api_manifest import parse_roles
roles = parse_roles(open(sys.argv[2], encoding='utf-8').read()) or {}
sys.exit(0 if 'accel_invalidate_all' in roles.get('introspection', ([], []))[1] else 1)
" "${ROOT}/pipeline/gates" "${ROOT}/backends/${ENGINE_NAME}/api/README.md"; then
  hooks+=("accel_invalidate_all()")
fi
[[ "$(engine_trait embedded)" == "True" ]] && hooks=()
for hook in "${hooks[@]}"; do
  out="$(echo "SELECT ${hook};" | engine_host sql - 2>&1)" \
    || fail "introspection hook ${hook} failed through host.sh sql" "${ENGINE_LOG}${out}"
done
emit_result "${JSON}" engine_api_conformance pass "" "${ENGINE_LOG}" "engine=${ENGINE_NAME}"
